use axum::{extract::{Path, State}, response::IntoResponse, Json};
use uuid::Uuid;
use crate::application::service::LoanService;
use crate::application::error::ApiError;
use crate::application::dto::LoanResponse;
use crate::app_state::AppState;

pub struct LoanHandler;

impl LoanHandler {
    #[tracing::instrument(skip(state), fields(loan_id = %loan_id))]
    pub async fn get(
        State(state): State<AppState>,
        Path(loan_id): Path<Uuid>,
    ) -> Result<Json<LoanResponse>, ApiError> {
        let svc = LoanService::new(state.loan_repo.clone());
        let loan = svc.get(loan_id).await?;
        Ok(Json(LoanResponse::from(loan)))
    }
}

use std::sync::Arc;
use uuid::Uuid;
use crate::application::error::ApiError;
use crate::application::repository::{LoanRepository, Loan};

pub struct LoanService {
    repo: Arc<dyn LoanRepository + Send + Sync>,
}

impl LoanService {
    pub fn new(repo: Arc<dyn LoanRepository + Send + Sync>) -> Self {
        Self { repo }
    }

    #[tracing::instrument(skip(self))]
    pub async fn get(&self, loan_id: Uuid) -> Result<Loan, ApiError> {
        self.repo
            .get_by_id(loan_id)
            .await
            .map_err(|e| match e {
                crate::application::repository::RepoError::NotFound => ApiError::NotFound,
                crate::application::repository::RepoError::Db(inner) => {
                    tracing::error!(error = ?inner, "loan repo db error");
                    ApiError::Dependency
                }
            })
    }
}

#[cfg(test)]
mod tests {
    use super::*;
    use crate::application::repository::{LoanRepository, Loan, RepoError};
    use async_trait::async_trait;
    use uuid::Uuid;

    struct StubRepo {
        outcome: Result<Loan, RepoError>,
    }

    #[async_trait]
    impl LoanRepository for StubRepo {
        async fn get_by_id(&self, _id: Uuid) -> Result<Loan, RepoError> {
            match &self.outcome {
                Ok(l) => Ok(l.clone()),
                Err(RepoError::NotFound) => Err(RepoError::NotFound),
                Err(RepoError::Db(_)) => Err(RepoError::Db("db down".into())),
            }
        }
    }

    #[tokio::test]
    async fn returns_loan_when_found() {
        let loan = Loan { id: Uuid::nil(), principal_cents: 100_00 };
        let repo = Arc::new(StubRepo { outcome: Ok(loan.clone()) });
        let svc = LoanService::new(repo);
        let got = svc.get(Uuid::nil()).await.unwrap();
        assert_eq!(got.principal_cents, 100_00);
    }

    #[tokio::test]
    async fn maps_not_found_to_api_error() {
        let repo = Arc::new(StubRepo { outcome: Err(RepoError::NotFound) });
        let svc = LoanService::new(repo);
        let err = svc.get(Uuid::nil()).await.unwrap_err();
        assert!(matches!(err, ApiError::NotFound));
    }

    #[tokio::test]
    async fn maps_db_error_to_dependency() {
        let repo = Arc::new(StubRepo { outcome: Err(RepoError::Db("x".into())) });
        let svc = LoanService::new(repo);
        let err = svc.get(Uuid::nil()).await.unwrap_err();
        assert!(matches!(err, ApiError::Dependency));
    }
}

use async_trait::async_trait;
use thiserror::Error;
use uuid::Uuid;

#[derive(Debug, Clone)]
pub struct Loan {
    pub id: Uuid,
    pub principal_cents: i64,
}

#[derive(Debug, Error)]
pub enum RepoError {
    #[error("not found")]
    NotFound,
    #[error("db error: {0}")]
    Db(String),
}

#[async_trait]
pub trait LoanRepository {
    async fn get_by_id(&self, id: Uuid) -> Result<Loan, RepoError>;
}

